/// Flutter bindings for the [fontations](https://github.com/googlefonts/fontations)
/// font stack, generated by [flutter_rust_bridge](https://github.com/fzyzcjy/flutter_rust_bridge).
///
/// Call [initFontations] once before using any other API:
///
/// ```dart
/// void main() async {
///   await initFontations();
///   final info = readFontInfo(bytes: await rootBundle.load('assets/font.ttf')
///       .then((d) => d.buffer.asUint8List()));
///   print(info.names.family);
/// }
/// ```
library;

import 'src/native_library.dart';
import 'src/rust/frb_generated.dart';

export 'src/color_glyph.dart';
export 'src/glyph_path.dart';
export 'src/rust/api/build.dart';
export 'src/rust/api/fontations.dart';
export 'src/rust/frb_generated.dart' show RustLib;

/// Loads and initializes the native Rust library.
///
/// Safe to call more than once; subsequent calls are no-ops.
///
/// The library is picked up in whichever shape it was built into the app:
/// dynamically from `rust/target/release` when running unpackaged, from the
/// `fontations.framework` bundle on SwiftPM based iOS/macOS apps, or from the
/// app executable itself when CocoaPods linked Rust statically.
Future<void> initFontations() async {
  await RustLib.init(externalLibrary: await loadFontationsExternalLibrary());
}
